                  <li
                    key={idx}
                    className="grid grid-cols-[100px_1fr] gap-2 items-center text-xs"
                  >
                    <span
                      className="truncate text-brand-ink font-semibold"
                      title={item.label}
                    >
                      {item.label.split(' ')[0] +
                        ' ' +
                        (item.label.split(' ')[1] || '')}
