                    <div className="flex items-center gap-2">
                      <div className="w-full bg-slate-100 rounded-full h-3 overflow-hidden border border-brand-line/30 flex-grow">
                        <div
                          className="bg-brand-accent h-full rounded-full"
                          style={{ width: `${item.percentual}%` }}
                        />
                      </div>
                      <span className="font-bold text-brand-ink-strong min-w-[20px] text-right">
                        {item.total} 🏅
                      </span>
                    </div>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-brand-muted flex items-center justify-center flex-grow text-xs italic">
                Nenhuma medalha emitida.
              </p>
            )}
          </article>
        </div>
      </section>
    </div>
  )
}

export default Dashboard

import React, { useState, useEffect } from 'react'
import { useNavigate, useParams, Link } from 'react-router-dom'
import db from '../../data/mockDb'
import type { Professor, Person, TurnoDisciplina } from '../../data/types'
import { FormSkeleton } from '../../components/ui'
import { toast } from '../../components/ui/Toast'

export const DisciplineForm: React.FC = () => {
  const navigate = useNavigate()
  const { id } = useParams<{ id: string }>()

  const [nome, setNome] = useState('')
  const [turno, setTurno] = useState<TurnoDisciplina | ''>('')
  const [professorId, setProfessorId] = useState('')
  const [descricao, setDescricao] = useState('')
  const [professors, setProfessors] = useState<Professor[]>([])
  const [people, setPeople] = useState<Person[]>([])
  const [loading, setLoading] = useState(true)

  // Load existing discipline and professor options
  useEffect(() => {
    const init = async () => {
      setLoading(true)
      try {
        const profs = await db.getProfessors()
        const ppl = await db.getPeople()
        setProfessors(profs)
        setPeople(ppl)

        if (id) {
          const disciplines = await db.getDisciplines()
          const found = disciplines.find((d) => d.id === id)
          if (found) {
            setNome(found.nome)
            setTurno(found.turno)
            setProfessorId(found.professorId)
            setDescricao(found.descricao)
          } else {
            toast.error('Disciplina não encontrada.')
          }
        }
      } catch (err: any) {
        toast.error(err.message || 'Erro ao carregar dados.')
      } finally {
        setLoading(false)
      }
    }
    init()
  }, [id])

  const professorList = professors.map((prof) => {
    const person = people.find((p) => p.id === prof.pessoaId)
    return {
      id: prof.id,
      name: person ? person.nome : prof.titulacao,
    }
  })

  const turnoOptions: Array<{ value: TurnoDisciplina; label: string }> = [
    { value: 'MATUTINO', label: 'Matutino' },
    { value: 'VESPERTINO', label: 'Vespertino' },
    { value: 'NOTURNO', label: 'Noturno' },
    { value: 'INTEGRAL', label: 'Integral' },
  ]

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!nome || !turno || !professorId) {
      toast.warning('Por favor, preencha todos os campos obrigatórios.')
      return
    }

    try {
      const payload = {
        id: id || undefined,
        nome,
        turno,
        professorId,
        descricao,
      }

      await db.saveDiscipline(payload)
      toast.success(
        id
          ? 'Disciplina atualizada com sucesso.'
          : 'Disciplina criada com sucesso.'
      )
      navigate('/admin/disciplinas')
    } catch (err: any) {
      toast.error(err.message || 'Erro ao salvar disciplina.')
    }
  }

  if (loading) {
    return (
      <div className="admin-page">
        <FormSkeleton fields={4} />
      </div>
    )
  }

  return (
    <div className="admin-page">
      <h1>{id ? 'Editar disciplina' : 'Nova disciplina'}</h1>

      <form className="event-form" onSubmit={handleSubmit}>
        <div className="form-grid">
          <label className="field">
            <span>Nome:*</span>
            <input
              type="text"
              value={nome}
              onChange={(e) => setNome(e.target.value)}
              placeholder="Nome da disciplina"
              required
            />
          </label>

          <label className="field">
            <span>Turno:*</span>
            <select
              value={turno}
              onChange={(e) => setTurno(e.target.value as TurnoDisciplina)}
              required
            >
              <option value="">Selecione um turno</option>
              {turnoOptions.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </label>

          <label className="field">
            <span>Professor:*</span>
            <select
              value={professorId}
              onChange={(e) => setProfessorId(e.target.value)}
              required
            >
              <option value="">Selecione um professor</option>
              {professorList.map((prof) => (
                <option key={prof.id} value={prof.id}>
                  {prof.name}
                </option>
              ))}
            </select>
          </label>

          <label className="field description-field">
            <span>Descrição:</span>
            <textarea
              value={descricao}
              onChange={(e) => setDescricao(e.target.value)}
              placeholder="Resumo da disciplina"
              rows={4}
            />
          </label>
        </div>

        <div className="form-actions">
          <Link to="/admin/disciplinas">Cancelar</Link>
          <button className="primary-action" type="submit">
            {id ? 'Salvar alterações' : 'Criar disciplina'}
          </button>
        </div>
      </form>
    </div>
  )
}

export default DisciplineForm

import React, { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { Plus } from 'lucide-react'
import db from '../../data/mockDb'
import type { Discipline, Professor, Person } from '../../data/types'
import { ButtonLink, PageHeader, TablePageSkeleton } from '../../components/ui'
import { toast } from '../../components/ui/Toast'

const turnoLabels: Record<string, string> = {
  MATUTINO: 'Matutino',
  VESPERTINO: 'Vespertino',
  NOTURNO: 'Noturno',
  INTEGRAL: 'Integral',
}

export const DisciplineList: React.FC = () => {
  const [disciplines, setDisciplines] = useState<Discipline[]>([])
  const [professors, setProfessors] = useState<Professor[]>([])
  const [people, setPeople] = useState<Person[]>([])
  const [loading, setLoading] = useState(true)

  const loadData = () => {
    setLoading(true)
    Promise.all([db.getDisciplines(), db.getProfessors(), db.getPeople()])
      .then(([discs, profs, ppl]) => {
        setDisciplines(discs)
        setProfessors(profs)
        setPeople(ppl)
      })
      .catch((err) =>
        toast.error(err.message || 'Erro ao carregar disciplinas.')
      )
      .finally(() => setLoading(false))
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleDelete = async (id: string) => {
    if (window.confirm('Excluir esta disciplina?')) {
      try {
        await db.deleteDiscipline(id)
        setDisciplines((prev) => prev.filter((d) => d.id !== id))
        toast.success('Disciplina excluída com sucesso.')
      } catch (err: any) {
        toast.error(err.message || 'Erro ao excluir disciplina.')
      }
    }
  }

  const getProfessorName = (profId: string) => {
    const prof = professors.find((p) => p.id === profId)
    const person = prof ? people.find((p) => p.id === prof.pessoaId) : null
    return person ? person.nome : '-'
  }

  if (loading) {
    return <TablePageSkeleton columns={5} rows={6} />
  }

  return (
    <div className="admin-page">
      <PageHeader
        eyebrow="Configuracao academica"
        title="Disciplinas"
        description="Mantenha a relacao entre disciplinas, turnos e professores responsaveis."
        actions={
          <ButtonLink
            to="/admin/disciplinas/novo"
            icon={<Plus aria-hidden="true" />}
          >
            Nova Disciplina
          </ButtonLink>
        }
      />

      <section className="people-panel">
        <table className="participants-table">
          <thead>
            <tr>
              <th>Nome</th>
              <th>Descrição</th>
              <th>Turno</th>
              <th>Professor</th>
              <th>Ações</th>
            </tr>
          </thead>
          <tbody>
            {disciplines.length === 0 ? (
              <tr>
                <td colSpan={5} className="text-center">
                  Nenhuma disciplina cadastrada.
                </td>
              </tr>
            ) : (
              disciplines.map((d) => (
                <tr key={d.id}>
                  <td>{d.nome}</td>
                  <td>{d.descricao}</td>
                  <td>{turnoLabels[d.turno] || d.turno}</td>
                  <td>{getProfessorName(d.professorId)}</td>
                  <td>
                    <div className="table-actions">
                      <Link
                        className="table-action"
                        to={`/admin/disciplinas/editar/${d.id}`}
                      >
                        Editar
                      </Link>
                      <button
                        className="table-action danger"
                        onClick={() => handleDelete(d.id)}
                      >
                        Excluir
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </section>
    </div>
  )
}

export default DisciplineList

import React, { useState, useEffect } from 'react'
import { useNavigate, useParams, Link } from 'react-router-dom'
import db from '../../data/mockDb'
import type { Event, Participation } from '../../data/types'
import { CompletionSkeleton } from '../../components/ui'
import { toast } from '../../components/ui/Toast'
// IMPORTA A FUNÇÃO DE UPLOAD
import { concluirEAssinarEvento } from '../../services/apiClient'

export const EventConclude: React.FC = () => {
  const navigate = useNavigate()
  const { id } = useParams<{ id: string }>()

  const [event, setEvent] = useState<Event | null>(null)
  const [participacoes, setParticipacoes] = useState<Participation[]>([])
  const [presentes, setPresentes] = useState<string[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [activeTab, setActiveTab] = useState<
    'TODOS' | 'PRESENTES' | 'AUSENTES'
  >('TODOS')
  const [currentPage, setCurrentPage] = useState(1)
  const PAGE_SIZE = 20

  // ESTADO PARA GUARDAR A IMAGEM
  const [assinaturaFile, setAssinaturaFile] = useState<File | null>(null)

  useEffect(() => {
    const loadData = async () => {
      if (!id) return
      setLoading(true)
      try {
        const [evt, parts] = await Promise.all([
          db.getEventById(id),
          db.getEventParticipations(id),
        ])
        setEvent(evt)
        setParticipacoes(parts)

        const initiallyPresent = parts
          .filter((p) => p.presente)
          .map((p) => p.id)
        setPresentes(initiallyPresent)
      } catch (err: any) {
        toast.error(err.message || 'Erro ao carregar dados do evento.')
      } finally {
        setLoading(false)
      }
    }
    loadData()
  }, [id])

  const parsedParticipacoes = participacoes.map((part) => {
    return {
      ...part,
      nome: part.pessoa?.nome || 'Participante nao informado',
      email: part.pessoa?.email || '-',
    }
  })

  const searchQueryLower = searchQuery.toLowerCase()
  const searchedParticipacoes = parsedParticipacoes.filter((part) => {
    const matchesName = part.nome.toLowerCase().includes(searchQueryLower)
    const matchesEmail = part.email.toLowerCase().includes(searchQueryLower)
    const matchesInscricao = part.inscricao
      .toString()
      .includes(searchQueryLower)
    return matchesName || matchesEmail || matchesInscricao
  })

  const filteredParticipacoes = searchedParticipacoes.filter((part) => {
    const isPresent = presentes.includes(part.id)
    if (activeTab === 'PRESENTES') return isPresent
    if (activeTab === 'AUSENTES') return !isPresent
    return true
  })

  const totalItems = filteredParticipacoes.length
  const totalPages = Math.ceil(totalItems / PAGE_SIZE) || 1

  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages)
    }
  }, [totalPages, currentPage])

  const startIndex = (currentPage - 1) * PAGE_SIZE
  const endIndex = Math.min(startIndex + PAGE_SIZE, totalItems)
  const paginatedParticipacoes = filteredParticipacoes.slice(
    startIndex,
    endIndex
  )

  const visibleSelected =
    paginatedParticipacoes.length > 0 &&
    paginatedParticipacoes.every((p) => presentes.includes(p.id))

  const handleToggleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    const visibleIds = paginatedParticipacoes.map((p) => p.id)
    if (e.target.checked) {
      setPresentes((prev) => {
        const next = [...prev]
        visibleIds.forEach((vid) => {
          if (!next.includes(vid)) {
            next.push(vid)
          }
        })
        return next
      })
    } else {
      setPresentes((prev) => prev.filter((vid) => !visibleIds.includes(vid)))
    }
  }

  const handleCheckboxChange = (partId: string, checked: boolean) => {
    if (checked) {
      setPresentes((prev) => [...prev, partId])
    } else {
      setPresentes((prev) => prev.filter((vid) => vid !== partId))
    }
  }

  // LÓGICA DE SUBMISSÃO COM A IMAGEM E LISTA DE PRESENTES
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!event) return

    if (!assinaturaFile) {
      toast.warning(
        'Selecione o arquivo da assinatura antes de concluir o evento.'
      )
      return
    }

    try {
      setLoading(true)

      // NOVO: Chama a nossa API enviando o ID do evento, a lista de presentes e a imagem
      await concluirEAssinarEvento(event.id, presentes, assinaturaFile)

      toast.success(
        'Evento concluído com sucesso e certificados gerados com a assinatura.'
      )
      navigate('/admin/certificados')
    } catch (err: any) {
      console.error(err)
      toast.error(
        err.message ||
          'Erro ao processar e concluir o evento. Verifique se o Back-end está rodando.'
      )
      setLoading(false)
    }
  }

  if (loading && !event) return <CompletionSkeleton />

  if (!event) {
    return (
      <div className="admin-page text-center py-12">
        <h2 className="text-xl text-brand-danger">Evento não encontrado.</h2>
        <Link to="/admin/eventos" className="primary-action mt-4">
          Voltar
        </Link>
      </div>
    )
  }

  const percentPresent =
    parsedParticipacoes.length > 0
      ? Math.round((presentes.length / parsedParticipacoes.length) * 100)
      : 0

  return (
    <div className="admin-page">
      <div className="page-title-row">
        <div>
          <h1>Concluir evento</h1>
          <p className="completion-subtitle text-sm text-brand-muted mt-1">
            {event.tema}
          </p>
        </div>
        <Link className="link-action" to="/admin/eventos">
          Voltar
        </Link>
      </div>

      <div className="completion-hero grid grid-cols-1 md:grid-cols-2 gap-4 mt-6 mb-8">
        <article className="summary-card p-4 bg-brand-surface border border-brand-line rounded-lg shadow-sm">
          <div className="flex items-center gap-2 text-xs text-brand-muted font-bold">
            <svg
              aria-hidden="true"
              className="w-4 h-4 text-brand-primary"
              viewBox="0 0 24 24"
            >
              <rect x="4" y="5" width="16" height="15" rx="2"></rect>
              <path d="M8 3v4M16 3v4M4 10h16"></path>
            </svg>
            <span>Data e horário</span>
          </div>
          <strong className="text-xl font-bold text-brand-ink-strong mt-2 block">
            {new Date(event.data).toLocaleDateString('pt-BR')}
          </strong>
          <small className="text-xs text-brand-muted mt-1 block">
            {event.horarioInicio} - {event.horarioFim}
          </small>
        </article>

        <article className="summary-card p-4 bg-brand-surface border border-brand-line rounded-lg shadow-sm">
          <div className="flex items-center gap-2 text-xs text-brand-muted font-bold">
            <svg
              aria-hidden="true"
              className="w-4 h-4 text-brand-primary"
              viewBox="0 0 24 24"
            >
              <circle cx="12" cy="12" r="9"></circle>
              <path d="M12 7v5l3 3"></path>
            </svg>
            <span>Status atual</span>
          </div>
          <strong className="text-xl font-bold text-brand-primary mt-2 block">
            {event.status.replace('_', ' ')}
          </strong>
          <small className="text-[10px] text-brand-primary font-bold mt-1 block uppercase">
            Somente presentes receberão certificado
          </small>
        </article>
      </div>

      <div
        style={{
          marginBottom: '1.5rem',
          padding: '1rem',
          backgroundColor: 'var(--surface)',
          border: '1px solid var(--line)',
          borderRadius: 'var(--radius)',
          boxShadow: 'var(--shadow-sm)',
        }}
      >
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginBottom: '0.5rem',
            fontSize: '0.85rem',
          }}
        >
          <span style={{ fontWeight: 'bold', color: 'var(--ink-strong)' }}>
            Taxa de Presença Geral
          </span>
          <span style={{ fontWeight: 'bold', color: 'var(--primary)' }}>
            {percentPresent}% ({presentes.length} de{' '}
            {parsedParticipacoes.length})
          </span>
        </div>
        <div
          style={{
            width: '100%',
            height: '0.6rem',
            backgroundColor: 'var(--line)',
            borderRadius: '999px',
            overflow: 'hidden',
          }}
        >
          <div
            style={{
              width: `${percentPresent}%`,
              height: '100%',
              backgroundColor: 'var(--primary)',
              transition: 'width 0.3s ease-out',
            }}
          />
        </div>
      </div>

      <div
        className="flex border-b border-brand-line mb-4"
        style={{
          display: 'flex',
          gap: '1rem',
          borderBottom: '1px solid var(--line)',
          marginBottom: '1.5rem',
        }}
      >
        {(['TODOS', 'PRESENTES', 'AUSENTES'] as const).map((tab) => {
          const count =
            tab === 'TODOS'
              ? parsedParticipacoes.length
              : tab === 'PRESENTES'
                ? presentes.length
                : parsedParticipacoes.length - presentes.length

          const label =
            tab === 'TODOS'
              ? 'Todos'
              : tab === 'PRESENTES'
                ? 'Presentes'
                : 'Não Confirmados'
          const isActive = activeTab === tab

          return (
            <button
              key={tab}
              type="button"
              onClick={() => {
                setActiveTab(tab)
                setCurrentPage(1)
              }}
              style={{
                background: 'none',
                border: 'none',
                padding: '0.75rem 0.5rem',
                cursor: 'pointer',
                borderBottom: isActive
                  ? '2px solid var(--primary)'
                  : '2px solid transparent',
                color: isActive ? 'var(--primary)' : 'var(--muted)',
                fontWeight: isActive ? 'bold' : 'normal',
                fontSize: '0.9rem',
                display: 'flex',
                alignItems: 'center',
                gap: '0.4rem',
              }}
            >
              <span>{label}</span>
              <span
                style={{
                  fontSize: '0.75rem',
                  padding: '0.1rem 0.45rem',
                  backgroundColor: isActive
                    ? 'var(--primary-soft)'
                    : 'var(--surface-soft)',
                  color: isActive ? 'var(--primary-strong)' : 'var(--muted)',
                  borderRadius: '999px',
                  fontWeight: 'bold',
                }}
              >
                {count}
              </span>
            </button>
          )
        })}
      </div>

      <div
        style={{
          display: 'flex',
          gap: '1rem',
          marginBottom: '1rem',
          flexWrap: 'wrap',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            border: '1px solid var(--line)',
            borderRadius: 'var(--radius)',
            backgroundColor: 'var(--surface)',
            padding: '0 0.75rem',
            flex: 1,
            minWidth: '260px',
            height: '2.55rem',
          }}
        >
          <svg
            style={{
              color: 'var(--muted)',
              marginRight: '0.5rem',
              width: '1rem',
              height: '1rem',
            }}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
          >
            <circle cx="11" cy="11" r="8"></circle>
            <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
          </svg>
          <input
            type="text"
            placeholder="Buscar por nome, e-mail ou inscrição..."
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value)
              setCurrentPage(1)
            }}
            style={{
              border: 'none',
              outline: 'none',
              width: '100%',
              fontSize: '0.88rem',
              backgroundColor: 'transparent',
              color: 'var(--ink)',
            }}
          />
          {searchQuery && (
            <button
              type="button"
              onClick={() => {
                setSearchQuery('')
                setCurrentPage(1)
              }}
              style={{
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                color: 'var(--muted)',
                fontWeight: 'bold',
                fontSize: '1.1rem',
              }}
            >
              ×
            </button>
          )}
        </div>

        {paginatedParticipacoes.length > 0 && (
          <label className="attendance-toggle flex items-center gap-2 text-xs font-bold text-brand-ink cursor-pointer">
            <input
              type="checkbox"
              checked={visibleSelected}
              onChange={handleToggleSelectAll}
              className="accent-brand-primary"
            />
            <span>
              Selecionar todos visíveis ({paginatedParticipacoes.length})
            </span>
          </label>
        )}
      </div>

      <form
        className="completion-form flex flex-col gap-4"
        onSubmit={handleSubmit}
      >
        {/* CAIXA DE UPLOAD DA ASSINATURA */}
        <div className="p-4 border border-brand-primary/30 rounded-lg bg-blue-50/30">
          <label className="block text-sm font-bold text-brand-ink-strong mb-2">
            Assinatura do Documento (Obrigatório)
          </label>
          <p className="text-xs text-brand-muted mb-3">
            Selecione o arquivo PNG ou JPG contendo a assinatura do responsável.
            Esta imagem será aplicada automaticamente em todos os certificados
            gerados.
          </p>
          <input
            type="file"
            accept="image/png, image/jpeg"
            required
            onChange={(e) => {
              if (e.target.files && e.target.files[0]) {
                setAssinaturaFile(e.target.files[0])
              }
            }}
            className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded file:border-0 file:bg-brand-primary file:text-white hover:file:bg-brand-primary-strong cursor-pointer bg-white border border-brand-line p-1"
          />
        </div>

        <section
          className="participants-section mt-2"
          aria-labelledby="participacoes-title"
        >
          {paginatedParticipacoes.length === 0 ? (
            <div className="empty-state compact-empty p-8 bg-brand-surface border border-brand-line rounded-lg text-center text-brand-muted">
              <p>Nenhuma participação encontrada para os filtros aplicados.</p>
            </div>
          ) : (
            <>
              <table className="participants-table">
                <thead>
                  <tr>
                    <th className="w-24 text-center">Presença</th>
                    <th>Inscrição</th>
                    <th>Participante</th>
                    <th>Tipo</th>
                    <th>Email</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedParticipacoes.map((part) => {
                    const isChecked = presentes.includes(part.id)
                    return (
                      <tr key={part.id}>
                        <td className="text-center">
                          <label className="attendance-check flex items-center justify-center cursor-pointer">
                            <input
                              type="checkbox"
                              name="presentes"
                              checked={isChecked}
                              onChange={(e) =>
                                handleCheckboxChange(part.id, e.target.checked)
                              }
                              className="w-4 h-4 accent-brand-primary"
                            />
                          </label>
                        </td>
                        <td>#{part.inscricao}</td>
                        <td>
                          <strong>{part.nome}</strong>
                        </td>
                        <td>{part.tipo}</td>
                        <td>{part.email}</td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>

              {totalPages > 1 && (
                <div
                  className="pagination"
                  style={{
                    display: 'flex',
                    justifyContent: 'center',
                    gap: '0.85rem',
                    marginTop: '1.5rem',
                    alignItems: 'center',
                  }}
                >
                  <button
                    type="button"
                    disabled={currentPage === 1}
                    onClick={() =>
                      setCurrentPage((prev) => Math.max(prev - 1, 1))
                    }
                    className="table-action"
                    style={{
                      cursor: currentPage === 1 ? 'not-allowed' : 'pointer',
                      opacity: currentPage === 1 ? 0.5 : 1,
                    }}
                  >
                    Anterior
                  </button>
                  <span style={{ fontSize: '0.85rem', color: 'var(--muted)' }}>
                    Página <strong>{currentPage}</strong> de {totalPages}
                  </span>
                  <button
                    type="button"
                    disabled={currentPage === totalPages}
                    onClick={() =>
                      setCurrentPage((prev) => Math.min(prev + 1, totalPages))
                    }
                    className="table-action"
                    style={{
                      cursor:
                        currentPage === totalPages ? 'not-allowed' : 'pointer',
                      opacity: currentPage === totalPages ? 0.5 : 1,
                    }}
                  >
                    Próxima
                  </button>
                </div>
              )}
            </>
          )}
        </section>

        <div className="form-actions completion-actions flex justify-end gap-3 mt-6">
          <Link
            to="/admin/eventos"
            className="px-4 py-2 border border-brand-line rounded-lg text-sm text-brand-muted hover:bg-slate-100"
          >
            Cancelar
          </Link>
          <button
            className="primary-action px-6 py-2 bg-brand-primary text-white font-bold rounded-lg hover:bg-brand-primary-strong transition-colors cursor-pointer text-sm"
            type="submit"
            disabled={loading || participacoes.length === 0}
          >
            {loading ? 'Processando...' : 'Gerar certificados e concluir'}
          </button>
        </div>
      </form>
    </div>
  )
}

export default EventConclude

import React, { useState, useEffect } from 'react'
import { useNavigate, useParams, Link } from 'react-router-dom'
import db from '../../data/mockDb'
import { AutocompleteInput } from '../../components/AutocompleteInput'
import type {
  Discipline,
  Sponsor,
  Local,
  Participation,
  Person,
  StatusEvento,
  ParticipanteEvento,
  TipoParticipacao,
} from '../../data/types'
import { FormSkeleton } from '../../components/ui'
import { toast } from '../../components/ui/Toast'

export const EventForm: React.FC = () => {
  const navigate = useNavigate()
  const { id } = useParams<{ id: string }>()

  const [tema, setTema] = useState('')
  const [data, setData] = useState('')
  const [horarioInicio, setHorarioInicio] = useState('')
  const [horarioFim, setHorarioFim] = useState('')
  const [modalidade, setModalidade] = useState<
    'PRESENCIAL' | 'ONLINE' | 'HIBRIDO'
  >('PRESENCIAL')
  const [disciplinaId, setDisciplinaId] = useState('')
  const [patrocinadorId, setPatrocinadorId] = useState('')
  const [localId, setLocalId] = useState('')
  const [descricao, setDescricao] = useState('')
  const [eventStatus, setEventStatus] = useState<StatusEvento>('CRIADO')

  const [disciplines, setDisciplines] = useState<Discipline[]>([])
  const [sponsors, setSponsors] = useState<Sponsor[]>([])
  const [locais, setLocais] = useState<Local[]>([])
  const [participacoes, setParticipacoes] = useState<Participation[]>([])
  const [people, setPeople] = useState<Person[]>([])
  const [selectedPessoaId, setSelectedPessoaId] = useState('')
  const [selectedTipo, setSelectedTipo] = useState<TipoParticipacao>('Aluno')
  const [eventParticipants, setEventParticipants] = useState<
    ParticipanteEvento[]
  >([])
  const [createdEventId, setCreatedEventId] = useState('')
  const [qrCodeInscricaoUrl, setQrCodeInscricaoUrl] = useState('')
  const [qrCodeConfirmacaoUrl, setQrCodeConfirmacaoUrl] = useState('')
  const [qrCodeLoading, setQrCodeLoading] = useState(false)
  const [showCreationModal, setShowCreationModal] = useState(false)

  const [loading, setLoading] = useState(true)
  const [step, setStep] = useState(1)

  // Load existing event and dropdown details
  useEffect(() => {
    const init = async () => {
      setLoading(true)
      try {
        const [discs, sps, locs, pps] = await Promise.all([
          db.getDisciplines(),
          db.getSponsors(),
          db.getLocais(),
          db.getPeople(),
        ])
        setDisciplines(discs)
        setSponsors(sps)
        setLocais(locs)
        setPeople(pps)

        if (id) {
          try {
            const found = await db.getEventById(id)
            if (found) {
              setTema(found.tema)
              setData(found.data)
              setHorarioInicio(found.horarioInicio)
              setHorarioFim(found.horarioFim)
              setModalidade(found.modalidade)
              setDisciplinaId(found.disciplinaId || '')
              setPatrocinadorId(found.patrocinadorId || '')
              setLocalId(found.localId || '')
              setDescricao(found.descricao || '')
              setEventStatus(found.status)

              // Try to load event-specific participations
              const parts = await db.getEventParticipations(id)
              setParticipacoes(parts)
              setEventParticipants(
                parts.map((part) => ({
                  id: part.id,
                  inscricao: part.inscricao,
                  pessoaId: part.pessoaId,
                  tipo: part.tipo,
                }))
              )
            } else {
              toast.error('Evento não encontrado.')
            }
          } catch (err) {
            // Fallback for finalized events since /participacoes endpoint might block
            const events = await db.getEvents()
            const found = events.find((e) => e.id === id)
            if (found) {
              setTema(found.tema)
              setData(found.data)
              setHorarioInicio(found.horarioInicio)
              setHorarioFim(found.horarioFim)
              setModalidade(found.modalidade)
              setDisciplinaId(found.disciplinaId || '')
              setPatrocinadorId(found.patrocinadorId || '')
              setLocalId(found.localId || '')
              setDescricao(found.descricao || '')
              setEventStatus(found.status)

              const allParts = await db.getParticipations()
              const eventParts = allParts.filter((p) => p.eventoId === id)
              setParticipacoes(eventParts)
              setEventParticipants(
                eventParts.map((part) => ({
                  id: part.id,
                  inscricao: part.inscricao,
                  pessoaId: part.pessoaId,
                  tipo: part.tipo,
                }))
              )
            } else {
              toast.error('Evento não encontrado.')
            }
          }
        }
      } catch (err: any) {
        toast.error(err.message || 'Erro ao carregar dados do formulário.')
      } finally {
        setLoading(false)
      }
    }
    init()
  }, [id])

  useEffect(
    () => () => {
      if (qrCodeInscricaoUrl) {
        URL.revokeObjectURL(qrCodeInscricaoUrl)
      }
      if (qrCodeConfirmacaoUrl) {
        URL.revokeObjectURL(qrCodeConfirmacaoUrl)
      }
    },
    [qrCodeInscricaoUrl, qrCodeConfirmacaoUrl]
  )

  const participacaoList = participacoes.map((part) => {
    const person = part.pessoa || people.find((p) => p.id === part.pessoaId)
    return {
      id: part.id,
      inscricao: part.inscricao,
      nome: person?.nome || 'Participante não informado',
      tipo: part.tipo,
      email: person?.email || '-',
    }
  })

  const participantRoles: TipoParticipacao[] = [
    'Aluno',
    'Professor',
    'Palestrante',
    'Organizador',
    'Colaborador',
  ]
  const peopleOptions = people.map((person) => ({
    id: person.id,
    label: `${person.nome} - ${person.email || person.cpf || 'sem contato'}`,
  }))
  const selectedParticipantsList = eventParticipants.map((part) => {
    const participation = participacoes.find(
      (item) => item.pessoaId === part.pessoaId
    )
    const person =
      participation?.pessoa || people.find((p) => p.id === part.pessoaId)
    return {
      ...part,
      nome: person?.nome || 'Participante nao informado',
      email: person?.email || '-',
    }
  })
  const nextInscricao =
    Math.max(
      1000,
      ...eventParticipants.map((part) => Number(part.inscricao) || 0),
      ...participacoes.map((part) => Number(part.inscricao) || 0)
    ) + 1

  const handleAddEventParticipant = () => {
    if (!selectedPessoaId) {
      toast.warning('Selecione uma pessoa para adicionar ao evento.')
      return
    }

    if (eventParticipants.some((part) => part.pessoaId === selectedPessoaId)) {
      toast.warning('Essa pessoa já foi adicionada ao evento.')
      return
    }

    setEventParticipants((prev) => [
      ...prev,
      {
        inscricao: String(nextInscricao),
        pessoaId: selectedPessoaId,
        tipo: selectedTipo,
      },
    ])
    setSelectedPessoaId('')
    setSelectedTipo('Aluno')
  }

  const handleRemoveEventParticipant = (pessoaId: string) => {
    setEventParticipants((prev) =>
      prev.filter((part) => part.pessoaId !== pessoaId)
    )
  }

  const loadQrCodes = async (eventId: string, attempt = 1) => {
    setQrCodeLoading(true)

    try {
      const [blobInscricao, blobConfirmacao] = await Promise.all([
        db.getEventQrCodeInscricaoBlob(eventId),
        db.getEventQrCodeConfirmacaoBlob(eventId),
      ])

      setQrCodeInscricaoUrl((previousUrl) => {
        if (previousUrl) URL.revokeObjectURL(previousUrl)
        return URL.createObjectURL(blobInscricao)
      })
      setQrCodeConfirmacaoUrl((previousUrl) => {
        if (previousUrl) URL.revokeObjectURL(previousUrl)
        return URL.createObjectURL(blobConfirmacao)
      })
    } catch (err) {
      if (attempt < 4) {
        window.setTimeout(() => loadQrCodes(eventId, attempt + 1), 900)
        return
      }
      toast.error(
        'Evento criado, mas os QR Codes ainda não ficaram disponíveis.'
      )
    } finally {
      setQrCodeLoading(false)
    }
  }

  const handleCloseCreationModal = () => {
    navigate('/admin/eventos')
  }

  const handleDownloadQrCode = () => {
    if (qrCodeInscricaoUrl) {
      const a = document.createElement('a')
      a.href = qrCodeInscricaoUrl
      a.download = `qrcode-inscricao-evento-${createdEventId || 'muttley'}.png`
      a.click()
    }
    if (qrCodeConfirmacaoUrl) {
      const a = document.createElement('a')
      a.href = qrCodeConfirmacaoUrl
      a.download = `qrcode-confirmacao-evento-${createdEventId || 'muttley'}.png`
      a.click()
    }
  }

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault()
  }

  const handleSave = async () => {
    if (step !== 3) {
      return
    }

    if (!tema || !data || !horarioInicio || !horarioFim || !modalidade) {
      toast.warning('Por favor, preencha todos os campos obrigatórios.')
      return
    }

    try {
      setLoading(true)
      const result = await db.saveEvent({
        id: id || undefined,
        tema,
        data,
        horarioInicio,
        horarioFim,
        modalidade,
        disciplinaId: disciplinaId || undefined,
        patrocinadorId: patrocinadorId || undefined,
        localId: localId || undefined,
        descricao,
        participacoes: eventParticipants,
      })

      if (!id && result.id) {
        toast.success('Evento criado com sucesso.')
        setCreatedEventId(result.id)
        setShowCreationModal(true)
        setLoading(false)
        loadQrCodes(result.id)
        return
      }

      toast.success('Evento atualizado com sucesso.')
      navigate('/admin/eventos')
    } catch (err: any) {
      toast.error(err.message || 'Erro ao salvar o evento.')
      setLoading(false)
    }
  }

  if (loading && step === 1 && !tema) {
    return (
      <div className="admin-page">
        <FormSkeleton fields={5} steps />
      </div>
    )
  }

  const isFinalized = eventStatus === 'FINALIZADO'

  const disciplineOptions = disciplines.map((d) => ({
    id: d.id,
    label: d.nome,
  }))
  const sponsorOptions = sponsors.map((s) => ({ id: s.id, label: s.nome }))
  const localOptions = locais.map((l) => ({ id: l.id, label: l.nome }))

  const steps = [
    { number: 1, label: 'Informações Gerais' },
    { number: 2, label: 'Local e Horário' },
    { number: 3, label: 'Vinculações' },
  ]

  const handleNextStep = () => {
    if (step === 1) {
      if (!tema) {
        toast.warning('Tema do evento é obrigatório.')
        return
      }
      setStep(2)
    } else if (step === 2) {
      if (!data || !horarioInicio || !horarioFim) {
        toast.warning('Data, horário de início e término são obrigatórios.')
        return
      }
      setStep(3)
    }
  }

  const handlePrevStep = () => {
    setStep((prev) => prev - 1)
  }

  return (
    <div className="admin-page">
      <h1>
        {id
          ? isFinalized
            ? 'Detalhes do evento'
            : 'Editar evento'
          : 'Novo evento'}
      </h1>

      {/* Step Indicator */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          marginBottom: '2rem',
          paddingBottom: '1rem',
          borderBottom: '1px solid var(--line)',
        }}
      >
        {steps.map((s, idx) => {
          const isActive = step === s.number
          const isCompleted = step > s.number
          return (
            <React.Fragment key={s.number}>
              <button
                type="button"
                onClick={() => {
                  if (isFinalized) {
                    setStep(s.number)
                    return
                  }
                  if (s.number < step) {
                    setStep(s.number)
                  } else {
                    if (step === 1) {
                      if (!tema) {
                        toast.warning('Tema do evento é obrigatório.')
                        return
                      }
                      setStep(s.number)
                    } else if (step === 2) {
                      if (!data || !horarioInicio || !horarioFim) {
                        toast.warning(
                          'Data, horário de início e término são obrigatórios.'
                        )
                        return
                      }
                      setStep(s.number)
                    }
                  }
                }}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.5rem',
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  padding: '0.5rem',
                  borderBottom: isActive
                    ? '2px solid var(--primary)'
                    : '2px solid transparent',
                  color: isActive
                    ? 'var(--primary)'
                    : isCompleted
                      ? 'var(--ink)'
                      : 'var(--muted)',
                  fontWeight: isActive ? 'bold' : 'normal',
                  transition: 'all 0.2s ease',
                }}
              >
                <span
                  style={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: '1.5rem',
                    height: '1.5rem',
                    borderRadius: '50%',
                    fontSize: '0.8rem',
                    fontWeight: 'bold',
                    backgroundColor: isActive
                      ? 'var(--primary)'
                      : isCompleted
                        ? 'var(--primary-soft)'
                        : 'var(--line)',
                    color: isActive ? '#fff' : 'var(--ink)',
                  }}
                >
                  {isCompleted ? '✓' : s.number}
                </span>
                <span className="step-label" style={{ fontSize: '0.85rem' }}>
                  {s.label}
                </span>
              </button>
              {idx < steps.length - 1 && (
                <div
                  style={{
                    flex: 1,
                    height: '1px',
                    backgroundColor: 'var(--line)',
                    margin: '0 1rem',
                  }}
                />
              )}
            </React.Fragment>
          )
        })}
      </div>

      <form className="event-form" onSubmit={handleFormSubmit}>
        {step === 1 && (
          <div className="form-grid">
            <label className="field col-span-2">
              <span>Tema do evento:*</span>
              <input
                type="text"
                value={tema}
                onChange={(e) => setTema(e.target.value)}
                placeholder="Nome ou tema do evento"
                required
                disabled={isFinalized}
              />
            </label>

            <label className="field col-span-2">
              <span>Modalidade:*</span>
              <select
                value={modalidade}
                onChange={(e) => setModalidade(e.target.value as any)}
                required
                disabled={isFinalized}
              >
                <option value="PRESENCIAL">Presencial</option>
                <option value="ONLINE">Online</option>
                <option value="HIBRIDO">Híbrido</option>
              </select>
            </label>

            <label className="field description-field col-span-2">
              <span>Descrição:</span>
              <textarea
                value={descricao}
                onChange={(e) => setDescricao(e.target.value)}
                placeholder="Descrição do evento"
                rows={4}
                disabled={isFinalized}
              />
            </label>
          </div>
        )}

        {step === 2 && (
          <div className="form-grid">
            <label className="field col-span-2">
              <span>Data:*</span>
              <input
                type="date"
                value={data}
                onChange={(e) => setData(e.target.value)}
                required
                disabled={isFinalized}
              />
            </label>

            <fieldset className="date-group">
              <legend className="text-sm font-semibold text-brand-ink-strong">
                Início:*
              </legend>
              <input
                type="time"
                value={horarioInicio}
                onChange={(e) => setHorarioInicio(e.target.value)}
                required
                disabled={isFinalized}
                className="border border-brand-line p-2 rounded-lg text-sm bg-brand-surface w-full mt-1.5"
              />
            </fieldset>

            <fieldset className="date-group">
              <legend className="text-sm font-semibold text-brand-ink-strong">
                Fim:*
              </legend>
              <input
                type="time"
                value={horarioFim}
                onChange={(e) => setHorarioFim(e.target.value)}
                required
                disabled={isFinalized}
                className="border border-brand-line p-2 rounded-lg text-sm bg-brand-surface w-full mt-1.5"
              />
            </fieldset>

            <div className="field col-span-2 description-field">
              <span>Local:</span>
              <AutocompleteInput
                options={localOptions}
                value={localId}
                onChange={setLocalId}
                placeholder="Buscar local..."
                disabled={isFinalized}
              />
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="form-grid">
            <div className="field col-span-2 description-field">
              <span>Disciplina:</span>
              <AutocompleteInput
                options={disciplineOptions}
                value={disciplinaId}
                onChange={setDisciplinaId}
                placeholder="Buscar disciplina..."
                disabled={isFinalized}
              />
            </div>

            <div className="field col-span-2 description-field">
              <span>Patrocinador:</span>
              <AutocompleteInput
                options={sponsorOptions}
                value={patrocinadorId}
                onChange={setPatrocinadorId}
                placeholder="Buscar patrocinador..."
                disabled={isFinalized}
              />
            </div>
          </div>
        )}

        <div
          className="form-actions"
          style={{ justifyContent: 'space-between' }}
        >
          <div>
            {step > 1 && (
              <button
                className="link-action"
                type="button"
                onClick={handlePrevStep}
                style={{
                  cursor: 'pointer',
                  background: 'var(--surface-soft)',
                  border: '1px solid var(--line)',
                }}
              >
                ← Voltar
              </button>
            )}
          </div>
          <div style={{ display: 'flex', gap: '0.75rem' }}>
            <Link to="/admin/eventos" className="link-action">
              Cancelar
            </Link>
            {step < 3 ? (
              <button
                className="primary-action"
                type="button"
                onClick={handleNextStep}
              >
                Avançar →
              </button>
            ) : (
              !isFinalized && (
                <button
                  className="primary-action"
                  type="button"
                  disabled={loading}
                  onClick={handleSave}
                >
                  {loading
                    ? 'Salvando...'
                    : id
                      ? 'Salvar alterações'
                      : 'Criar evento'}
                </button>
              )
            )}
          </div>
        </div>
      </form>

      <section
        className="event-participant-builder"
        aria-labelledby="event-participants-title"
      >
        <div className="participants-heading">
          <div>
            <h2 id="event-participants-title">Participantes do evento</h2>
            <p>Adicione pessoas e defina o papel de cada uma no evento.</p>
          </div>
        </div>

        {!isFinalized && (
          <div className="event-participant-builder__controls">
            <div className="field">
              <span>Pessoa:</span>
              <AutocompleteInput
                options={peopleOptions}
                value={selectedPessoaId}
                onChange={setSelectedPessoaId}
                placeholder="Buscar participante..."
              />
            </div>

            <label className="field">
              <span>Papel:</span>
              <select
                value={selectedTipo}
                onChange={(e) =>
                  setSelectedTipo(e.target.value as TipoParticipacao)
                }
              >
                {participantRoles.map((role) => (
                  <option key={role} value={role}>
                    {role}
                  </option>
                ))}
              </select>
            </label>

            <button
              className="primary-action"
              type="button"
              onClick={handleAddEventParticipant}
            >
              Adicionar
            </button>
          </div>
        )}

        {selectedParticipantsList.length === 0 ? (
          <div className="empty-state compact-empty">
            <p>Nenhum participante adicionado.</p>
          </div>
        ) : (
          <div className="ui-table-wrap">
            <table className="participants-table event-participants-table">
              <thead>
                <tr>
                  <th>Inscricao</th>
                  <th>Participante</th>
                  <th>Papel</th>
                  <th>Email</th>
                  <th>{isFinalized ? 'Medalha' : 'Acoes'}</th>
                </tr>
              </thead>
              <tbody>
                {selectedParticipantsList.map((part) => {
                  const participation = participacoes.find(
                    (item) => item.pessoaId === part.pessoaId
                  )
                  return (
                    <tr key={part.pessoaId}>
                      <td>#{part.inscricao}</td>
                      <td>
                        <strong>{part.nome}</strong>
                      </td>
                      <td>{part.tipo}</td>
                      <td>{part.email}</td>
                      <td>
                        {isFinalized && participation ? (
                          <Link
                            to={`/admin/medalhas/novo?participacaoId=${participation.id}`}
                            className="table-action font-semibold"
                          >
                            Adicionar Medalha
                          </Link>
                        ) : !isFinalized ? (
                          <button
                            className="table-action"
                            type="button"
                            onClick={() =>
                              handleRemoveEventParticipant(part.pessoaId)
                            }
                          >
                            Remover
                          </button>
                        ) : (
                          <span className="text-xs text-brand-muted">-</span>
                        )}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>

      {showCreationModal && (
        <div className="modal-backdrop" role="presentation">
          <section
            className="creation-confirmation-modal"
            role="dialog"
            aria-modal="true"
            aria-labelledby="creation-confirmation-title"
          >
            <button
              className="modal-close-button"
              type="button"
              aria-label="Fechar"
              onClick={handleCloseCreationModal}
            >
              x
            </button>

            <div className="creation-confirmation-modal__header">
              <span>Evento criado</span>
              <h2 id="creation-confirmation-title">
                QR Codes gerados para o evento
              </h2>
              <p>
                Compartilhe os QR Codes com os participantes e organizadores.
              </p>
            </div>

            <div
              style={{
                display: 'grid',
                gridTemplateColumns: '1fr 1fr',
                gap: '1.5rem',
                margin: '1rem 0',
              }}
            >
              {/* QR Inscrição */}
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '0.5rem',
                }}
              >
                <span
                  style={{
                    fontSize: '0.8rem',
                    fontWeight: 'bold',
                    color: 'var(--muted)',
                    textTransform: 'uppercase',
                    letterSpacing: '0.05em',
                  }}
                >
                  Inscrição
                </span>
                <div className="creation-confirmation-modal__qr">
                  {qrCodeInscricaoUrl ? (
                    <img src={qrCodeInscricaoUrl} alt="QR Code de inscrição" />
                  ) : (
                    <div
                      className="creation-confirmation-modal__placeholder"
                      role="status"
                    >
                      Gerando QR Code...
                    </div>
                  )}
                </div>
                <span
                  style={{
                    fontSize: '0.75rem',
                    color: 'var(--muted)',
                    textAlign: 'center',
                  }}
                >
                  Participante escaneia para se inscrever
                </span>
              </div>

              {/* QR Confirmação */}
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '0.5rem',
                }}
              >
                <span
                  style={{
                    fontSize: '0.8rem',
                    fontWeight: 'bold',
                    color: 'var(--muted)',
                    textTransform: 'uppercase',
                    letterSpacing: '0.05em',
                  }}
                >
                  Confirmação de presença
                </span>
                <div className="creation-confirmation-modal__qr">
                  {qrCodeConfirmacaoUrl ? (
                    <img
                      src={qrCodeConfirmacaoUrl}
                      alt="QR Code de confirmação de presença"
                    />
                  ) : (
                    <div
                      className="creation-confirmation-modal__placeholder"
                      role="status"
                    >
                      Gerando QR Code...
                    </div>
                  )}
                </div>
                <span
                  style={{
                    fontSize: '0.75rem',
                    color: 'var(--muted)',
                    textAlign: 'center',
                  }}
                >
                  Participante escaneia no dia do evento
                </span>
              </div>
            </div>

            <div className="creation-confirmation-modal__actions">
              <button
                className="link-action"
                type="button"
                onClick={handleDownloadQrCode}
                disabled={
                  (!qrCodeInscricaoUrl && !qrCodeConfirmacaoUrl) ||
                  qrCodeLoading
                }
              >
                Baixar QR Codes
              </button>
              <button
                className="primary-action"
                type="button"
                onClick={handleCloseCreationModal}
              >
                Concluir
              </button>
            </div>
          </section>
        </div>
      )}

      {false && id && isFinalized && (
        <section
          className="participants-section mt-8"
          aria-labelledby="participacoes-title"
        >
          <div className="participants-heading mb-4">
            <h2
              id="participacoes-title"
              className="text-lg font-bold text-brand-ink-strong"
            >
              Participações ({participacaoList.length})
            </h2>
          </div>

          {participacaoList.length === 0 ? (
            <div className="empty-state compact-empty p-6 bg-brand-surface border border-brand-line rounded-lg text-center text-brand-muted">
              <p>Nenhuma participação cadastrada para este evento.</p>
            </div>
          ) : (
            <div className="ui-table-wrap">
              <table className="participants-table event-participants-table">
                <thead>
                  <tr>
                    <th>Inscrição</th>
                    <th>Participante</th>
                    <th>Tipo</th>
                    <th>Email</th>
                    {isFinalized && <th>Medalha</th>}
                  </tr>
                </thead>
                <tbody>
                  {participacaoList.map((part) => (
                    <tr key={part.id}>
                      <td>#{part.inscricao}</td>
                      <td>
                        <strong>{part.nome}</strong>
                      </td>
                      <td>{part.tipo}</td>
                      <td>{part.email}</td>
                      {isFinalized && (
                        <td>
                          <Link
                            to={`/admin/medalhas/novo?participacaoId=${part.id}`}
                            className="table-action font-semibold"
                          >
                            Adicionar Medalha
                          </Link>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      )}
    </div>
  )
}

export default EventForm

import React, { useState, useMemo, useRef, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { Plus } from 'lucide-react'
import db from '../../data/mockDb'
import type { Evento, Local, Discipline, Sponsor } from '../../data/types'
import {
  ButtonLink,
  EmptyState,
  EventListSkeleton,
  PageHeader,
  StatusBadge,
} from '../../components/ui'
import { toast } from '../../components/ui/Toast'

export const EventList: React.FC = () => {
  const [busca, setBusca] = useState('')
  const [statusFiltro, setStatusFiltro] = useState('')
  const [ordenar, setOrdenar] = useState('data')
  const [tamanho, setTamanho] = useState(10)
  const [pagina, setPagina] = useState(0)
  const [qrModalEvent, setQrModalEvent] = useState<Evento | null>(null)
  const [qrCodeInscricaoUrl, setQrCodeInscricaoUrl] = useState('')
  const [qrCodeConfirmacaoUrl, setQrCodeConfirmacaoUrl] = useState('')
  const [qrCodeLoading, setQrCodeLoading] = useState(false)

  const carouselRef = useRef<HTMLDivElement>(null)

  // Load state datasets
  const [events, setEvents] = useState<Evento[]>([])
  const [locations, setLocations] = useState<Local[]>([])
  const [disciplines, setDisciplines] = useState<Discipline[]>([])
  const [sponsors, setSponsors] = useState<Sponsor[]>([])
  const [loading, setLoading] = useState(true)

  const loadData = () => {
    setLoading(true)
    Promise.all([
      db.getEvents(),
      db.getLocais(),
      db.getDisciplines(),
      db.getSponsors(),
    ])
      .then(([evts, locs, discs, spons]) => {
        setEvents(evts)
        setLocations(locs)
        setDisciplines(discs)
        setSponsors(spons)
      })
      .catch((err) => toast.error(err.message || 'Erro ao carregar eventos.'))
      .finally(() => setLoading(false))
  }

  useEffect(() => {
    loadData()
  }, [])

  useEffect(
    () => () => {
      if (qrCodeInscricaoUrl) {
        URL.revokeObjectURL(qrCodeInscricaoUrl)
      }
      if (qrCodeConfirmacaoUrl) {
        URL.revokeObjectURL(qrCodeConfirmacaoUrl)
      }
    },
    [qrCodeInscricaoUrl, qrCodeConfirmacaoUrl]
  )

  const activeEvents = useMemo(
    () => events.filter((e) => e.status === 'EM_ANDAMENTO'),
    [events]
  )

  const [canScroll, setCanScroll] = useState(false)

  const checkScroll = () => {
    if (carouselRef.current) {
      const { scrollWidth, clientWidth } = carouselRef.current
      setCanScroll(scrollWidth > clientWidth)
    }
  }

  useEffect(() => {
    checkScroll()
    window.addEventListener('resize', checkScroll)
    return () => window.removeEventListener('resize', checkScroll)
  }, [activeEvents])

  const scrollCarousel = (direction: 'left' | 'right') => {
    if (carouselRef.current) {
      const scrollAmount = direction === 'left' ? -336 : 336
      carouselRef.current.scrollBy({ left: scrollAmount, behavior: 'smooth' })
    }
  }

  const handleCancel = async (id: string) => {
    if (window.confirm('Cancelar este evento?')) {
      try {
        await db.cancelEvent(id)
        toast.success('Evento cancelado com sucesso.')
        // Refresh event list
        const evts = await db.getEvents()
        setEvents(evts)
      } catch (err: any) {
        toast.error(err.message || 'Erro ao cancelar evento.')
      }
    }
  }

  const openQrCodeModal = async (evento: Evento) => {
    setQrModalEvent(evento)
    setQrCodeLoading(true)
    setQrCodeInscricaoUrl((prev) => {
      if (prev) URL.revokeObjectURL(prev)
      return ''
    })
    setQrCodeConfirmacaoUrl((prev) => {
      if (prev) URL.revokeObjectURL(prev)
      return ''
    })

    try {
      const [blobInscricao, blobConfirmacao] = await Promise.all([
        db.getEventQrCodeInscricaoBlob(evento.id),
        db.getEventQrCodeConfirmacaoBlob(evento.id),
      ])
      setQrCodeInscricaoUrl(URL.createObjectURL(blobInscricao))
      setQrCodeConfirmacaoUrl(URL.createObjectURL(blobConfirmacao))
    } catch (err: any) {
      toast.error(err.message || 'Não foi possível carregar os QR Codes.')
    } finally {
      setQrCodeLoading(false)
    }
  }

  const closeQrCodeModal = () => {
    setQrModalEvent(null)
    setQrCodeLoading(false)
    setQrCodeInscricaoUrl((prev) => {
      if (prev) URL.revokeObjectURL(prev)
      return ''
    })
    setQrCodeConfirmacaoUrl((prev) => {
      if (prev) URL.revokeObjectURL(prev)
      return ''
    })
  }

  const handleDownloadQrCode = () => {
    if (!qrModalEvent) return
    if (qrCodeInscricaoUrl) {
      const a = document.createElement('a')
      a.href = qrCodeInscricaoUrl
      a.download = `qrcode-inscricao-evento-${qrModalEvent.id || 'muttley'}.png`
      a.click()
    }
    if (qrCodeConfirmacaoUrl) {
      const a = document.createElement('a')
      a.href = qrCodeConfirmacaoUrl
      a.download = `qrcode-confirmacao-evento-${qrModalEvent.id || 'muttley'}.png`
      a.click()
    }
  }

  // Filter and sort events
  const filteredEvents = useMemo(() => {
    let result = [...events]

    // Filter by search query
    if (busca.trim()) {
      const query = busca.toLowerCase()
      result = result.filter(
        (e) =>
          e.tema.toLowerCase().includes(query) ||
          (e.descricao && e.descricao.toLowerCase().includes(query))
      )
    }

    // Filter by status
    if (statusFiltro) {
      result = result.filter((e) => e.status === statusFiltro)
    }

    // Sort
    result.sort((a, b) => {
      if (ordenar === 'tema') {
        return a.tema.localeCompare(b.tema)
      }
      const dateDiff = new Date(a.data).getTime() - new Date(b.data).getTime()
      if (dateDiff !== 0) return dateDiff
      return (a.horarioInicio || '').localeCompare(b.horarioInicio || '')
    })

    return result
  }, [events, busca, statusFiltro, ordenar])

  // Paginated events
  const paginatedEvents = useMemo(() => {
    const start = pagina * tamanho
    return filteredEvents.slice(start, start + tamanho)
  }, [filteredEvents, pagina, tamanho])

  const totalPages = Math.ceil(filteredEvents.length / tamanho)

  if (loading) {
    return <EventListSkeleton />
  }

  return (
    <div className="admin-page">
      <PageHeader
        eyebrow="Gestao academica"
        title="Eventos"
        description="Cadastre, acompanhe e conclua atividades academicas com controle de inscricoes e certificados."
        actions={
          <ButtonLink
            to="/admin/eventos/novo"
            icon={<Plus aria-hidden="true" />}
          >
            Novo Evento
          </ButtonLink>
        }
      />

      {activeEvents.length > 0 && (
        <section
          className="events-section mb-8"
          aria-labelledby="active-events-title"
        >
          <div className="section-heading mb-4">
            <h2
              id="active-events-title"
              className="text-lg font-bold text-brand-ink-strong"
            >
              Eventos em andamento
            </h2>
          </div>

          <div className="events-carousel relative">
            {canScroll && (
              <button
                className="carousel-control previous"
                type="button"
                aria-label="Evento anterior"
                onClick={() => scrollCarousel('left')}
              >
                <svg aria-hidden="true" viewBox="0 0 24 24">
                  <path d="m15 18-6-6 6-6"></path>
                </svg>
              </button>
            )}

            <div className="events-row scroll-smooth" ref={carouselRef}>
              {activeEvents.map((evento) => {
                const local = locations.find((l) => l.id === evento.localId)
                const dateObj = new Date(evento.data)
                const day = evento.data ? dateObj.getDate() + 1 : 12
                const month = evento.data
                  ? dateObj.toLocaleDateString('pt-BR', { month: '2-digit' })
                  : '05'

                return (
                  <article
                    key={evento.id}
                    className="event-card flex flex-col p-4 bg-brand-surface border border-brand-line rounded-lg shadow-sm w-[320px] shrink-0 relative overflow-hidden"
                  >
                    <div className="event-main flex justify-between items-start">
                      <h3 className="text-sm font-bold text-brand-ink-strong max-w-[200px]">
                        {evento.tema}
                      </h3>
                      <time className="px-2.5 py-1 bg-brand-primary-soft text-brand-primary-strong rounded-full text-xs font-bold flex items-center gap-1">
                        <svg
                          className="w-3.5 h-3.5"
                          aria-hidden="true"
                          viewBox="0 0 24 24"
                        >
                          <rect
                            x="4"
                            y="5"
                            width="16"
                            height="15"
                            rx="2"
                          ></rect>
                          <path d="M8 3v4M16 3v4M4 10h16"></path>
                        </svg>
                        <span>
                          {day}/{month}
                        </span>
                      </time>
                    </div>

                    <p className="event-location flex items-center gap-1.5 text-xs text-brand-muted mt-2 font-semibold">
                      <svg
                        className="w-3.5 h-3.5 text-brand-primary"
                        aria-hidden="true"
                        viewBox="0 0 24 24"
                      >
                        <path d="M12 21s7-5.3 7-12a7 7 0 0 0-14 0c0 6.7 7 12 7 12z"></path>
                        <circle cx="12" cy="9" r="2.2"></circle>
                      </svg>
                      <span>{local?.nome || 'Local não definido'}</span>
                    </p>

                    <p className="event-description text-xs text-brand-muted mt-2 flex-grow line-clamp-2">
                      {evento.descricao || 'Sem descrição cadastrada.'}
                    </p>

                    <div className="event-footer flex items-center justify-between mt-4 text-xs text-brand-muted border-t border-brand-line/40 pt-2.5">
                      <span className="flex items-center gap-1">
                        <svg
                          className="w-3.5 h-3.5"
                          aria-hidden="true"
                          viewBox="0 0 24 24"
                        >
                          <circle cx="12" cy="12" r="9"></circle>
                          <path d="M12 7v5l4 2"></path>
                        </svg>
                        <span>
                          {evento.horarioInicio} - {evento.horarioFim}
                        </span>
                      </span>
                      <Link
                        className="event-footer-action text-white bg-brand-primary px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-brand-primary-strong transition-colors"
                        to={`/admin/eventos/concluir/${evento.id}`}
                      >
                        Concluir evento
                      </Link>
                    </div>
                  </article>
                )
              })}
            </div>

            {canScroll && (
              <button
                className="carousel-control next"
                type="button"
                aria-label="Próximo evento"
                onClick={() => scrollCarousel('right')}
              >
                <svg aria-hidden="true" viewBox="0 0 24 24">
                  <path d="m9 18 6-6-6-6"></path>
                </svg>
              </button>
            )}
          </div>
        </section>
      )}

      <section className="summary-grid grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        <article className="summary-card p-4 bg-brand-surface border border-brand-line rounded-lg shadow-sm">
          <div className="flex items-center gap-2 text-xs text-brand-muted font-bold">
            <svg
              aria-hidden="true"
              className="w-4 h-4 text-brand-primary"
              viewBox="0 0 24 24"
            >
              <rect x="4" y="5" width="16" height="15" rx="2"></rect>
              <path d="M8 3v4M16 3v4M4 10h16"></path>
            </svg>
            <span>Eventos exibidos</span>
          </div>
          <strong className="text-2xl font-extrabold text-brand-ink-strong mt-2 block">
            {filteredEvents.length}
          </strong>
        </article>

        <article className="summary-card p-4 bg-brand-surface border border-brand-line rounded-lg shadow-sm">
          <div className="flex items-center gap-2 text-xs text-brand-muted font-bold">
            <svg
              aria-hidden="true"
              className="w-4 h-4 text-brand-primary"
              viewBox="0 0 24 24"
            >
              <rect x="4" y="5" width="16" height="15" rx="2"></rect>
              <path d="M8 3v4M16 3v4M4 10h16"></path>
            </svg>
            <span>Página atual</span>
          </div>
          <strong className="text-2xl font-extrabold text-brand-ink-strong mt-2 block">
            {pagina + 1} / {totalPages || 1}
          </strong>
        </article>

        <article className="summary-card p-4 bg-brand-surface border border-brand-line rounded-lg shadow-sm">
          <div className="flex items-center gap-2 text-xs text-brand-muted font-bold">
            <svg
              aria-hidden="true"
              className="w-4 h-4 text-brand-primary"
              viewBox="0 0 24 24"
            >
              <path d="M16 21v-2a4 4 0 0 0-8 0v2"></path>
              <circle cx="12" cy="7" r="4"></circle>
            </svg>
            <span>Exibindo</span>
          </div>
          <strong className="text-2xl font-extrabold text-brand-ink-strong mt-2 block">
            {paginatedEvents.length}
          </strong>
        </article>

        <article className="summary-card p-4 bg-brand-surface border border-brand-line rounded-lg shadow-sm">
          <div className="flex items-center gap-2 text-xs text-brand-muted font-bold">
            <svg
              aria-hidden="true"
              className="w-4 h-4 text-brand-primary"
              viewBox="0 0 24 24"
            >
              <rect x="4" y="5" width="16" height="15" rx="2"></rect>
              <path d="M8 3v4M16 3v4M4 10h16"></path>
            </svg>
            <span>Por página</span>
          </div>
          <strong className="text-2xl font-extrabold text-brand-ink-strong mt-2 block">
            {tamanho}
          </strong>
        </article>
      </section>

      <form
        className="events-toolbar grid grid-cols-1 sm:grid-cols-2 md:grid-cols-5 gap-3 mb-6"
        onSubmit={(e) => e.preventDefault()}
      >
        <label className="search-field bg-brand-surface border border-brand-line p-2 rounded-lg flex items-center gap-2 focus-within:border-brand-primary">
          <svg className="w-4 h-4 text-brand-muted" viewBox="0 0 24 24">
            <circle cx="11" cy="11" r="7"></circle>
            <path d="m20 20-3.5-3.5"></path>
          </svg>
          <input
            type="search"
            value={busca}
            onChange={(e) => {
              setBusca(e.target.value)
              setPagina(0)
            }}
            placeholder="Buscar evento"
            className="w-full text-sm outline-none bg-transparent"
          />
        </label>

        <select
          value={ordenar}
          onChange={(e) => setOrdenar(e.target.value)}
          className="border border-brand-line p-2 rounded-lg text-sm bg-brand-surface"
        >
          <option value="data">Ordenar por: Data</option>
          <option value="tema">Ordenar por: Nome</option>
        </select>

        <select
          value={statusFiltro}
          onChange={(e) => {
            setStatusFiltro(e.target.value)
            setPagina(0)
          }}
          className="border border-brand-line p-2 rounded-lg text-sm bg-brand-surface"
        >
          <option value="">Todos os status</option>
          <option value="CRIADO">Criado</option>
          <option value="EM_ANDAMENTO">Em andamento</option>
          <option value="FINALIZADO">Finalizado</option>
          <option value="CANCELADO">Cancelado</option>
        </select>

        <select
          value={tamanho}
          onChange={(e) => {
            setTamanho(Number(e.target.value))
            setPagina(0)
          }}
          className="border border-brand-line p-2 rounded-lg text-sm bg-brand-surface"
        >
          <option value="5">Exibir: 5 itens</option>
          <option value="10">Exibir: 10 itens</option>
          <option value="25">Exibir: 25 itens</option>
          <option value="50">Exibir: 50 itens</option>
        </select>

        <button
          type="button"
          onClick={() => {
            setBusca('')
            setStatusFiltro('')
            setOrdenar('data')
            setPagina(0)
          }}
          className="bg-brand-muted hover:bg-slate-700 text-white rounded-lg text-xs font-bold transition-colors cursor-pointer"
        >
          Limpar Filtros
        </button>
      </form>

      <section className="event-list flex flex-col gap-4">
        {paginatedEvents.length === 0 ? (
          <EmptyState
            title="Nenhum evento encontrado"
            description="Ajuste os filtros ou cadastre um novo evento."
          />
        ) : (
          paginatedEvents.map((evento) => {
            const local = locations.find((l) => l.id === evento.localId)
            const disc = disciplines.find((d) => d.id === evento.disciplinaId)
            const sponsor = sponsors.find((s) => s.id === evento.patrocinadorId)
            const isFinalized = evento.status === 'FINALIZADO'
            const isCancelled = evento.status === 'CANCELADO'
            const dateObj = new Date(evento.data)
            const day = evento.data ? dateObj.getDate() + 1 : 12
            const month = evento.data
              ? dateObj
                  .toLocaleDateString('pt-BR', { month: 'short' })
                  .replace('.', '')
              : 'mai'

            return (
              <article
                key={evento.id}
                className="event-list-card event-list-card--redesigned"
              >
                <div
                  className="event-list-date"
                  aria-label={`Data do evento: ${day} de ${month}`}
                >
                  <strong>{day}</strong>
                  <span>{month}</span>
                  <small>{evento.horarioInicio}</small>
                </div>
                <div className="event-list-meta flex flex-col gap-2 md:border-r border-brand-line md:pr-4 justify-center text-xs text-brand-muted">
                  <span className="flex items-center gap-1.5 font-semibold">
                    <svg
                      className="w-4 h-4 text-brand-primary"
                      viewBox="0 0 24 24"
                    >
                      <path d="M12 21s7-5.3 7-12a7 7 0 0 0-14 0c0 6.7 7 12 7 12z"></path>
                      <circle cx="12" cy="9" r="2.2"></circle>
                    </svg>
                    <span>{local?.nome || '—'}</span>
                  </span>
                  <span className="flex items-center gap-1.5">
                    <svg
                      className="w-4 h-4 text-brand-primary"
                      viewBox="0 0 24 24"
                    >
                      <rect x="4" y="5" width="16" height="15" rx="2"></rect>
                      <path d="M8 3v4M16 3v4M4 10h16"></path>
                    </svg>
                    <span>
                      {day}/{month} | {evento.horarioInicio} -{' '}
                      {evento.horarioFim}
                    </span>
                  </span>
                </div>

                <div className="event-list-content min-w-0">
                  <h2 className="text-lg font-bold text-brand-ink-strong truncate mb-2">
                    {evento.tema}
                  </h2>
                  <div className="event-list-details">
                    <span>
                      <svg viewBox="0 0 24 24" aria-hidden="true">
                        <path d="M12 21s7-5.3 7-12a7 7 0 0 0-14 0c0 6.7 7 12 7 12z"></path>
                        <circle cx="12" cy="9" r="2.2"></circle>
                      </svg>
                      {local?.nome || 'Local nao definido'}
                    </span>
                    <span>
                      <svg viewBox="0 0 24 24" aria-hidden="true">
                        <circle cx="12" cy="12" r="9"></circle>
                        <path d="M12 7v5l4 2"></path>
                      </svg>
                      {evento.horarioInicio} - {evento.horarioFim}
                    </span>
                  </div>
                  <div className="event-tags flex flex-wrap gap-2 text-xs text-brand-muted mb-2">
                    <StatusBadge status={evento.status} />
                    {disc && (
                      <span className="flex items-center gap-1">
                        <svg
                          className="w-3.5 h-3.5 text-brand-primary"
                          viewBox="0 0 24 24"
                        >
                          <path d="M4 19.5V5a2 2 0 0 1 2-2h12v18H6a2 2 0 0 1-2-1.5z"></path>
                        </svg>
                        <span>{disc.nome}</span>
                      </span>
                    )}
                    {sponsor && (
                      <span className="flex items-center gap-1">
                        <svg
                          className="w-3.5 h-3.5 text-brand-primary"
                          viewBox="0 0 24 24"
                        >
                          <circle cx="12" cy="12" r="9"></circle>
                          <path d="M8 12h8M12 8v8"></path>
                        </svg>
                        <span>{sponsor.nome}</span>
                      </span>
                    )}
                    <span className="capitalize px-2 py-0.5 rounded border border-brand-line">
                      {evento.modalidade.toLowerCase()}
                    </span>
                  </div>
                  <p className="text-xs text-brand-muted leading-relaxed line-clamp-2 mt-1">
                    {evento.descricao || 'Nenhuma descrição cadastrada.'}
                  </p>
                </div>

                <div className="event-actions">
                  <Link
                    className="event-action event-action--primary"
                    to={`/admin/eventos/editar/${evento.id}`}
                  >
                    {isFinalized ? 'Ver detalhes' : 'Editar'}
                  </Link>

                  {(evento.qrCodeInscricaoUrl ||
                    evento.qrCodeConfirmacaoUrl) && (
                    <button
                      type="button"
                      onClick={() => openQrCodeModal(evento)}
                      className="event-action event-action--secondary"
                    >
                      Ver QR Code
                    </button>
                  )}

                  {!isFinalized && !isCancelled && (
                    <div className="event-actions__secondary">
                      <Link
                        className="event-action event-action--secondary"
                        to={`/admin/eventos/concluir/${evento.id}`}
                      >
                        Concluir
                      </Link>
                      <button
                        className="event-action event-action--danger"
                        type="button"
                        onClick={() => handleCancel(evento.id)}
                      >
                        Cancelar
                      </button>
                    </div>
                  )}
                </div>
              </article>
            )
          })
        )}
      </section>

      {/* Pagination */}
      {totalPages > 1 && (
        <nav className="pagination mt-6 flex justify-center gap-1 text-xs font-bold text-brand-muted">
          <button
            onClick={() => setPagina(0)}
            disabled={pagina === 0}
            className={`px-3 py-1.5 rounded-full ${pagina === 0 ? 'opacity-40 cursor-not-allowed' : 'hover:bg-brand-primary hover:text-white'}`}
          >
            Primeiro
          </button>
          <button
            onClick={() => setPagina((p) => Math.max(0, p - 1))}
            disabled={pagina === 0}
            className={`px-3 py-1.5 rounded-full ${pagina === 0 ? 'opacity-40 cursor-not-allowed' : 'hover:bg-brand-primary hover:text-white'}`}
          >
            Anterior
          </button>

          {Array.from({ length: totalPages }).map((_, idx) => (
            <button
              key={idx}
              onClick={() => setPagina(idx)}
              className={`px-3 py-1.5 rounded-full ${pagina === idx ? 'bg-brand-primary text-white' : 'hover:bg-brand-primary hover:text-white'}`}
            >
              {idx + 1}
            </button>
          ))}

          <button
            onClick={() => setPagina((p) => Math.min(totalPages - 1, p + 1))}
            disabled={pagina === totalPages - 1}
            className={`px-3 py-1.5 rounded-full ${pagina === totalPages - 1 ? 'opacity-40 cursor-not-allowed' : 'hover:bg-brand-primary hover:text-white'}`}
          >
            Próximo
          </button>
          <button
            onClick={() => setPagina(totalPages - 1)}
            disabled={pagina === totalPages - 1}
            className={`px-3 py-1.5 rounded-full ${pagina === totalPages - 1 ? 'opacity-40 cursor-not-allowed' : 'hover:bg-brand-primary hover:text-white'}`}
          >
            Último
          </button>
        </nav>
      )}

      {qrModalEvent && (
        <div className="modal-backdrop" role="presentation">
          <section
            className="creation-confirmation-modal"
            role="dialog"
            aria-modal="true"
            aria-labelledby="event-qrcode-title"
          >
            <button
              className="modal-close-button"
              type="button"
              aria-label="Fechar"
              onClick={closeQrCodeModal}
            >
              x
            </button>

            <div className="creation-confirmation-modal__header">
              <span>QR Codes</span>
              <h2 id="event-qrcode-title">{qrModalEvent.tema}</h2>
              <p>
                Compartilhe os QR Codes com os participantes e organizadores.
              </p>
            </div>

            <div
              style={{
                display: 'grid',
                gridTemplateColumns: '1fr 1fr',
                gap: '1.5rem',
                margin: '1rem 0',
              }}
            >
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '0.5rem',
                }}
              >
                <span
                  style={{
                    fontSize: '0.8rem',
                    fontWeight: 'bold',
                    color: 'var(--muted)',
                    textTransform: 'uppercase',
                    letterSpacing: '0.05em',
                  }}
                >
                  Inscrição
                </span>
                <div className="creation-confirmation-modal__qr">
                  {qrCodeInscricaoUrl ? (
                    <img src={qrCodeInscricaoUrl} alt="QR Code de inscrição" />
                  ) : (
                    <div
                      className="creation-confirmation-modal__placeholder"
                      role="status"
                    >
                      Carregando...
                    </div>
                  )}
                </div>
                <span
                  style={{
                    fontSize: '0.75rem',
                    color: 'var(--muted)',
                    textAlign: 'center',
                  }}
                >
                  Participante escaneia para se inscrever
                </span>
              </div>

              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '0.5rem',
                }}
              >
                <span
                  style={{
                    fontSize: '0.8rem',
                    fontWeight: 'bold',
                    color: 'var(--muted)',
                    textTransform: 'uppercase',
                    letterSpacing: '0.05em',
                  }}
                >
                  Confirmação de presença
                </span>
                <div className="creation-confirmation-modal__qr">
                  {qrCodeConfirmacaoUrl ? (
                    <img
                      src={qrCodeConfirmacaoUrl}
                      alt="QR Code de confirmação de presença"
                    />
                  ) : (
                    <div
                      className="creation-confirmation-modal__placeholder"
                      role="status"
                    >
                      Carregando...
                    </div>
                  )}
                </div>
                <span
                  style={{
                    fontSize: '0.75rem',
                    color: 'var(--muted)',
                    textAlign: 'center',
                  }}
                >
                  Participante escaneia no dia do evento
                </span>
              </div>
            </div>

            <div className="creation-confirmation-modal__actions">
              <button
                className="link-action"
                type="button"
                onClick={handleDownloadQrCode}
                disabled={
                  (!qrCodeInscricaoUrl && !qrCodeConfirmacaoUrl) ||
                  qrCodeLoading
                }
              >
                Baixar QR Codes
              </button>
              <button
                className="primary-action"
                type="button"
                onClick={closeQrCodeModal}
              >
                Fechar
              </button>
            </div>
          </section>
        </div>
      )}
    </div>
  )
}

export default EventList

import React, { useState, useEffect } from 'react'
import { useNavigate, useParams, Link } from 'react-router-dom'
import db from '../../data/mockDb'
import type { Address } from '../../data/types'
import { FormSkeleton } from '../../components/ui'
import { toast } from '../../components/ui/Toast'

export const LocalForm: React.FC = () => {
  const navigate = useNavigate()
  const { id } = useParams<{ id: string }>()

  const [nome, setNome] = useState('')
  const [capacidade, setCapacidade] = useState(10)
  const [enderecoId, setEnderecoId] = useState('')
  const [descricao, setDescricao] = useState('')
  const [addresses, setAddresses] = useState<Address[]>([])
  const [loading, setLoading] = useState(true)

  // Load existing local and addresses
  useEffect(() => {
    const init = async () => {
      setLoading(true)
      try {
        const addrs = await db.getAddresses()
        setAddresses(addrs)

        if (id) {
          const locais = await db.getLocais()
          const found = locais.find((l) => l.id === id)
          if (found) {
            setNome(found.nome)
            setCapacidade(found.capacidade)
            setEnderecoId(found.enderecoId)
            setDescricao(found.descricao)
          } else {
            toast.error('Local não encontrado.')
          }
        }
      } catch (err: any) {
        toast.error(err.message || 'Erro ao carregar dados.')
      } finally {
        setLoading(false)
      }
    }
    init()
  }, [id])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!nome || !capacidade || !enderecoId) {
      toast.warning('Por favor, preencha todos os campos obrigatórios.')
      return
    }

    try {
      const payload = {
        id: id || undefined,
        nome,
        capacidade: Number(capacidade),
        enderecoId,
        descricao,
      }

      await db.saveLocal(payload)
      toast.success(
        id ? 'Local atualizado com sucesso.' : 'Local criado com sucesso.'
      )
      navigate('/admin/locais')
    } catch (err: any) {
      toast.error(err.message || 'Erro ao salvar local.')
    }
  }

  if (loading) {
    return (
      <div className="admin-page">
        <FormSkeleton fields={4} />
      </div>
    )
  }

  return (
    <div className="admin-page">
      <h1>{id ? 'Editar local' : 'Novo local'}</h1>

      <form className="event-form" onSubmit={handleSubmit}>
        <div className="form-grid">
          <label className="field">
            <span>Nome:*</span>
            <input
              type="text"
              value={nome}
              onChange={(e) => setNome(e.target.value)}
              placeholder="Nome do local"
              required
            />
          </label>

          <label className="field">
            <span>Capacidade:*</span>
            <input
              type="number"
              value={capacidade}
              onChange={(e) => setCapacidade(Number(e.target.value))}
              min={1}
              placeholder="Ex: 120"
              required
            />
          </label>

          <label className="field">
            <span>Endereço:*</span>
            <select
              value={enderecoId}
              onChange={(e) => setEnderecoId(e.target.value)}
              required
            >
              <option value="">Selecione um endereço</option>
              {addresses.map((addr) => (
                <option key={addr.id} value={addr.id}>
                  {addr.logradouro}, {addr.numero} - {addr.cidade}
                </option>
              ))}
            </select>
          </label>

          <label className="field description-field">
            <span>Descrição:</span>
            <textarea
              value={descricao}
              onChange={(e) => setDescricao(e.target.value)}
              placeholder="Resumo do local"
              rows={4}
            />
          </label>
        </div>

        <div className="form-actions">
          <Link to="/admin/locais">Cancelar</Link>
          <button className="primary-action" type="submit">
            {id ? 'Salvar alterações' : 'Criar local'}
          </button>
        </div>
      </form>
    </div>
  )
}

export default LocalForm

import React, { useState, useEffect } from 'react'
import { useNavigate, useParams, useSearchParams, Link } from 'react-router-dom'
import db from '../../data/mockDb'
import type {
  Participation,
  Person,
  Event,
  TipoMedalha,
} from '../../data/types'
import { FormSkeleton } from '../../components/ui'
import { toast } from '../../components/ui/Toast'

const medalTypes: Array<{
  value: TipoMedalha
  label: string
  description: string
}> = [
  {
    value: 'BRONZE',
    label: 'Bronze',
    description: 'Reconhecimento de participacao',
  },
  {
    value: 'PRATA',
    label: 'Prata',
    description: 'Destaque por contribuicao relevante',
  },
  {
    value: 'OURO',
    label: 'Ouro',
    description: 'Maior nivel de reconhecimento',
  },
]

export const MedalForm: React.FC = () => {
  const navigate = useNavigate()
  const { id } = useParams<{ id: string }>()
  const [searchParams] = useSearchParams()
  const participacaoIdParam = searchParams.get('participacaoId')

  const [nome, setNome] = useState('')
  const [participacaoId, setParticipacaoId] = useState('')
  const [descricao, setDescricao] = useState('')
  const [tipo, setTipo] = useState<TipoMedalha>('BRONZE')
  const [participacoes, setParticipacoes] = useState<Participation[]>([])
  const [events, setEvents] = useState<Event[]>([])
  const [people, setPeople] = useState<Person[]>([])
  const [loading, setLoading] = useState(true)

  // Load existing medal and options
  useEffect(() => {
    const init = async () => {
      setLoading(true)
      try {
        const [parts, evts, pps] = await Promise.all([
          db.getParticipations(),
          db.getEvents(),
          db.getPeople(),
        ])
        setParticipacoes(parts)
        setEvents(evts)
        setPeople(pps)

        if (id) {
          const medals = await db.getMedals()
          const found = medals.find((m) => m.id === id)
          if (found) {
            setNome(found.nome)
            setParticipacaoId(found.participacaoId)
            setDescricao(found.descricao)
            setTipo(found.tipo)
          } else {
            toast.error('Medalha não encontrada.')
          }
        } else if (participacaoIdParam) {
          setParticipacaoId(participacaoIdParam)
        }
      } catch (err: any) {
        toast.error(err.message || 'Erro ao carregar dados.')
      } finally {
        setLoading(false)
      }
    }
    init()
  }, [id, participacaoIdParam])

  const options = participacoes.map((part) => {
    const person = part.pessoa || people.find((p) => p.id === part.pessoaId)
    const event = part.evento || events.find((e) => e.id === part.eventoId)
    return {
      id: part.id,
      text: `#${part.inscricao} - ${person ? person.nome : 'Participante'} - ${event ? event.tema : 'Evento'}`,
    }
  })

  // Selected participation info for preview banner
  const selectedPart = participacoes.find((p) => p.id === participacaoId)
  const selectedPerson = selectedPart
    ? selectedPart.pessoa || people.find((p) => p.id === selectedPart.pessoaId)
    : null
  const selectedEvent = selectedPart
    ? selectedPart.evento || events.find((e) => e.id === selectedPart.eventoId)
    : null

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!nome || !participacaoId || !descricao || !tipo) {
      toast.warning('Por favor, preencha todos os campos obrigatórios.')
      return
    }

    try {
      setLoading(true)
      await db.saveMedal({
        id: id || undefined,
        nome,
        participacaoId,
        descricao,
        tipo,
      })
      toast.success(
        id ? 'Medalha atualizada com sucesso.' : 'Medalha criada com sucesso.'
      )
      navigate('/admin/medalhas')
    } catch (err: any) {
      toast.error(err.message || 'Erro ao salvar medalha.')
      setLoading(false)
    }
  }

  if (loading && !nome && id) {
    return (
      <div className="admin-page">
        <FormSkeleton fields={5} />
      </div>
    )
  }

  return (
    <div className="admin-page">
      <h1>{id ? 'Editar medalha' : 'Nova medalha'}</h1>

      <form className="event-form" onSubmit={handleSubmit}>
        <div className="form-grid">
          <label className="field">
            <span>Nome:*</span>
            <input
              type="text"
              value={nome}
              onChange={(e) => setNome(e.target.value)}
              placeholder="Nome da medalha (ex: Destaque, Melhor Palestrante)"
              required
            />
          </label>

          <label className="field">
            <span>Participação:*</span>
            <select
              value={participacaoId}
              onChange={(e) => setParticipacaoId(e.target.value)}
              required
            >
              <option value="">Selecione uma participação</option>
              {options.map((opt) => (
                <option key={opt.id} value={opt.id}>
                  {opt.text}
                </option>
              ))}
            </select>
          </label>

          <fieldset className="field description-field medal-type-field">
            <legend>Tipo da medalha:*</legend>
            <div className="medal-type-selector">
              {medalTypes.map((option) => (
                <label
                  key={option.value}
                  className={`medal-type-option medal-type-option--${option.value.toLowerCase()} ${
                    tipo === option.value ? 'is-selected' : ''
                  }`}
                >
                  <input
                    type="radio"
                    name="tipo"
                    value={option.value}
                    checked={tipo === option.value}
                    onChange={() => setTipo(option.value)}
                  />
                  <span
                    className="medal-type-option__mark"
                    aria-hidden="true"
                  />
                  <strong>{option.label}</strong>
                  <small>{option.description}</small>
                </label>
              ))}
            </div>
          </fieldset>

          {selectedPart && selectedPerson && selectedEvent && (
            <div className="selected-participation description-field col-span-2 p-4 bg-brand-surface-soft border border-brand-line rounded-lg flex flex-col gap-1">
              <span className="text-[10px] uppercase font-bold text-brand-muted">
                Participante Selecionado
              </span>
              <strong className="text-sm font-bold text-brand-ink-strong">
                {selectedPerson.nome}
              </strong>
              <small className="text-xs text-brand-muted">
                Inscrição #{selectedPart.inscricao} - {selectedEvent.tema}
              </small>
            </div>
          )}

          <label className="field description-field">
            <span>Descrição da Conquista:*</span>
            <textarea
              value={descricao}
              onChange={(e) => setDescricao(e.target.value)}
              placeholder="Descreva o motivo da concessão da medalha..."
              rows={4}
              required
            />
          </label>
        </div>

        <div className="form-actions">
          <Link to="/admin/medalhas">Cancelar</Link>
          <button className="primary-action" type="submit" disabled={loading}>
            {loading
              ? 'Salvando...'
              : id
                ? 'Salvar alterações'
                : 'Criar medalha'}
          </button>
        </div>
      </form>
    </div>
  )
}

export default MedalForm

import React, { useState } from 'react'
import { useParams } from 'react-router-dom'
import apiClient from '../../services/apiClient'
import { toast } from '../../components/ui/Toast'

export const ConfirmarPresenca: React.FC = () => {
  const { id } = useParams<{ id: string }>()
  const [cpf, setCpf] = useState('')
  const [loading, setLoading] = useState(false)

  const formatCpf = (value: string) => {
    const digits = value.replace(/\D/g, '').slice(0, 11)
    return digits
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})$/, '$1-$2')
  }

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault()

    if (!id) {
      toast.error(
        'Evento não identificado. Verifique o QR Code e tente novamente.'
      )
      return
    }
    if (!cpf.trim()) {
      toast.warning('Informe seu CPF.')
      return
    }
    if (!/^\d{3}\.\d{3}\.\d{3}-\d{2}$/.test(cpf.trim())) {
      toast.warning('CPF inválido. Use o formato 000.000.000-00.')
      return
    }

    try {
      setLoading(true)
      const response = await apiClient.post(
        `/eventos/${id}/confirmar-presenca/${cpf}`
      )
      toast.success(
        response.data?.message ??
          response.data ??
          'Presença confirmada com sucesso!'
      )
      setCpf('')
    } catch (err: any) {
      toast.error(
        err.message ||
          'Não foi possível confirmar sua presença. Tente novamente.'
      )
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="public-certificate-page">
      <div className="public-certificate-panel">
        <div className="public-event-signup-panel">
          <span>Confirmação de presença</span>
          <h2>Registre sua presença</h2>

          <form onSubmit={handleSubmit}>
            <label className="field">
              <span>CPF:*</span>
              <input
                type="text"
                placeholder="000.000.000-00"
                value={cpf}
                onChange={(event) => setCpf(formatCpf(event.target.value))}
                disabled={loading}
                inputMode="numeric"
                maxLength={14}
                required
              />
            </label>

            <button className="primary-action" type="submit" disabled={loading}>
              {loading ? 'Confirmando...' : 'Confirmar presença'}
            </button>
          </form>
        </div>
      </div>
    </div>
  )
}

export default ConfirmarPresenca

import React, { useEffect, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { CalendarDays, Clock, MapPin } from 'lucide-react'
import db from '../../data/mockDb'
import type { PublicEvent } from '../../data/types'
import { PublicEventDetailSkeleton, StatusBadge } from '../../components/ui'
import { toast } from '../../components/ui/Toast'

export const PublicEventDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>()
  const loggedUser = db.getLoggedUser()
  const [event, setEvent] = useState<PublicEvent | null>(null)
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [form, setForm] = useState({
    nomeCompleto: '',
    cpf: '',
    email: '',
  })

  useEffect(() => {
    if (!id) return
    setLoading(true)
    db.getPublicEventById(id)
      .then(setEvent)
      .catch((err) => toast.error(err.message || 'Evento nao encontrado.'))
      .finally(() => setLoading(false))
  }, [id])

  const handleCpfChange = (
    changeEvent: React.ChangeEvent<HTMLInputElement>
  ) => {
    let value = changeEvent.target.value.replace(/\D/g, '')
    if (value.length > 11) value = value.slice(0, 11)

    value = value.replace(/(\d{3})(\d)/, '$1.$2')
    value = value.replace(/(\d{3})(\d)/, '$1.$2')
    value = value.replace(/(\d{3})(\d{1,2})$/, '$1-$2')

    setForm((current) => ({ ...current, cpf: value }))
  }

  const submitInscription = async (
    payload: { nomeCompleto: string; cpf: string; email: string },
    options: { fromLoggedUser?: boolean } = {}
  ) => {
    if (!id || !event) return

    const normalizedPayload = {
      nomeCompleto: payload.nomeCompleto.trim(),
      cpf: payload.cpf.trim(),
      email: payload.email.trim(),
    }

    if (
      !normalizedPayload.nomeCompleto ||
      !normalizedPayload.email ||
      !normalizedPayload.cpf
    ) {
      toast.warning(
        options.fromLoggedUser
          ? 'Nao foi possivel localizar nome, CPF e e-mail da sua conta. Saia e entre novamente.'
          : 'Preencha nome, CPF e e-mail para concluir a inscricao.'
      )
      return
    }

    try {
      setSubmitting(true)
      const response = await db.createPublicInscription(id, {
        nomeCompleto: normalizedPayload.nomeCompleto,
        cpf: normalizedPayload.cpf,
        email: normalizedPayload.email,
      })
      toast.success(
        `${response.message} Numero de inscricao: #${response.inscricao}`
      )
      setForm({ nomeCompleto: '', cpf: '', email: '' })
    } catch (err: any) {
      toast.error(err.message || 'Nao foi possivel realizar sua inscricao.')
    } finally {
      setSubmitting(false)
    }
  }

  const handleSubmit = async (submitEvent: React.FormEvent) => {
    submitEvent.preventDefault()
    await submitInscription(form)
  }

  const handleLoggedUserSignup = async () => {
    if (!loggedUser) return

    let userData = loggedUser

    try {
      userData = await db.getMe()
    } catch (err) {
      console.error(
        'Nao foi possivel atualizar os dados do usuario logado pelo endpoint /me.',
        err
      )
      toast.warning(
        'Não foi possível atualizar os dados da sua conta. Usaremos os dados salvos neste dispositivo.'
      )
    }

    await submitInscription(
      {
        nomeCompleto: userData.nome,
        cpf: userData.cpf,
        email: userData.email,
      },
      { fromLoggedUser: true }
    )
  }

  if (loading) {
    return <PublicEventDetailSkeleton />
  }

  if (!event) {
    return (
      <main className="public-event-detail-page">
        <div className="public-event-not-found">
          <h1>Evento nao encontrado</h1>
          <Link className="primary-action" to="/eventos">
            Voltar aos eventos
          </Link>
        </div>
      </main>
    )
  }

  const date = event.data ? new Date(`${event.data}T00:00:00`) : null
  const formattedDate = date
    ? date.toLocaleDateString('pt-BR', {
        weekday: 'long',
        day: '2-digit',
        month: 'long',
        year: 'numeric',
      })
    : 'Data nao informada'

  return (
    <main className="public-event-detail-page">
      <Link className="public-event-back" to="/eventos">
        Voltar aos eventos
      </Link>

      <section className="public-event-detail-layout">
        <article className="public-event-detail-main">
          <div className="public-event-detail-kicker">
            <StatusBadge
              status={event.inscricoesEncerradas ? 'FINALIZADO' : event.status}
              label={
                event.inscricoesEncerradas ? 'Inscricoes encerradas' : undefined
              }
            />
            <span>{event.modalidade.toLowerCase()}</span>
          </div>

          <h1>{event.tema}</h1>
          <p>{event.descricao || 'Evento academico da Fatec Zona Leste.'}</p>

          <div className="public-event-detail-meta">
            <span>
              <CalendarDays aria-hidden="true" />
              {formattedDate}
            </span>
            <span>
              <Clock aria-hidden="true" />
              {event.horarioInicio} - {event.horarioFim}
            </span>
            <span>
              <MapPin aria-hidden="true" />
              {event.local || 'Local nao informado'}
            </span>
          </div>

          {event.disciplina && (
            <div className="public-event-detail-discipline">
              <span>Disciplina</span>
              <strong>{event.disciplina}</strong>
            </div>
          )}
        </article>

        <aside className="public-event-signup-panel">
          <span>Inscricao</span>
          <h2>
            {event.inscricoesEncerradas
              ? 'Inscricoes encerradas'
              : 'Reserve sua participacao'}
          </h2>

          {loggedUser ? (
            <div className="public-event-logged-signup">
              <p>
                Vamos usar os dados da sua conta para confirmar a inscricao.
              </p>
              <strong>{loggedUser.nome}</strong>
              <small>{loggedUser.email}</small>
              <button
                className="primary-action"
                type="button"
                onClick={handleLoggedUserSignup}
                disabled={event.inscricoesEncerradas || submitting}
              >
                {submitting
                  ? 'Enviando...'
                  : event.inscricoesEncerradas
                    ? 'Inscricoes encerradas'
                    : 'Inscrever-se'}
              </button>
            </div>
          ) : (
            <form onSubmit={handleSubmit}>
              <label className="field">
                <span>Nome completo:*</span>
                <input
                  type="text"
                  placeholder="Seu nome completo"
                  value={form.nomeCompleto}
                  onChange={(changeEvent) =>
                    setForm((current) => ({
                      ...current,
                      nomeCompleto: changeEvent.target.value,
                    }))
                  }
                  disabled={event.inscricoesEncerradas || submitting}
                  required
                />
              </label>

              <label className="field">
                <span>CPF:*</span>
                <input
                  type="text"
                  placeholder="000.000.000-00"
                  value={form.cpf}
                  onChange={handleCpfChange}
                  disabled={event.inscricoesEncerradas || submitting}
                  required
                />
              </label>

              <label className="field">
                <span>E-mail:*</span>
                <input
                  type="email"
                  placeholder="seu.email@exemplo.com"
                  value={form.email}
                  onChange={(changeEvent) =>
                    setForm((current) => ({
                      ...current,
                      email: changeEvent.target.value,
                    }))
                  }
                  disabled={event.inscricoesEncerradas || submitting}
                  required
                />
              </label>

              <button
                className="primary-action"
                type="submit"
                disabled={event.inscricoesEncerradas || submitting}
              >
                {submitting
                  ? 'Enviando...'
                  : event.inscricoesEncerradas
                    ? 'Inscricoes encerradas'
                    : 'Inscrever-se'}
              </button>
            </form>
          )}
        </aside>
      </section>
    </main>
  )
}

export default PublicEventDetail

import React, { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { CalendarDays, Clock, MapPin, Search } from 'lucide-react'
import db from '../../data/mockDb'
import type { PublicEvent } from '../../data/types'
import {
  EmptyState,
  PublicEventListSkeleton,
  StatusBadge,
} from '../../components/ui'
import { toast } from '../../components/ui/Toast'

export const PublicEventList: React.FC = () => {
  const [events, setEvents] = useState<PublicEvent[]>([])
  const [loading, setLoading] = useState(true)
  const [query, setQuery] = useState('')

  useEffect(() => {
    setLoading(true)
    db.getPublicEvents()
      .then(setEvents)
      .catch((err) =>
        toast.error(err.message || 'Nao foi possivel carregar os eventos.')
      )
      .finally(() => setLoading(false))
  }, [])

  const filteredEvents = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase()
    const sorted = [...events].sort((a, b) => {
      const dateDiff = new Date(a.data).getTime() - new Date(b.data).getTime()
      if (dateDiff !== 0) return dateDiff
      return a.horarioInicio.localeCompare(b.horarioInicio)
    })

    if (!normalizedQuery) return sorted

    return sorted.filter((event) =>
      [event.tema, event.descricao, event.disciplina, event.local]
        .filter(Boolean)
        .some((value) => String(value).toLowerCase().includes(normalizedQuery))
    )
  }, [events, query])

  if (loading) {
    return <PublicEventListSkeleton />
  }

  return (
    <main className="public-events-page">
      <section className="public-events-hero">
        <div>
          <span>Fatec Zona Leste</span>
          <h1>Eventos abertos</h1>
          <p>
            Confira a agenda academica e faca sua inscricao sem precisar criar
            conta.
          </p>
        </div>

        <label className="public-events-search">
          <Search aria-hidden="true" />
          <input
            type="search"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Buscar por tema, disciplina ou local"
          />
        </label>
      </section>

      {filteredEvents.length === 0 ? (
        <EmptyState
          title="Nenhum evento encontrado"
          description="Novos eventos aparecem aqui quando forem publicados."
        />
      ) : (
        <section
          className="public-events-grid"
          aria-label="Lista de eventos publicos"
        >
          {filteredEvents.map((event) => {
            const date = event.data ? new Date(`${event.data}T00:00:00`) : null
            const day = date
              ? date.toLocaleDateString('pt-BR', { day: '2-digit' })
              : '--'
            const month = date
              ? date
                  .toLocaleDateString('pt-BR', { month: 'short' })
                  .replace('.', '')
              : '---'

            return (
              <article key={event.id} className="public-event-card">
                <div className="public-event-card__date">
                  <strong>{day}</strong>
                  <span>{month}</span>
                </div>

                <div className="public-event-card__body">
                  <div className="public-event-card__top">
                    <StatusBadge
                      status={
                        event.inscricoesEncerradas ? 'FINALIZADO' : event.status
                      }
                      label={
                        event.inscricoesEncerradas
                          ? 'Inscricoes encerradas'
                          : undefined
                      }
                    />
                    <span>{event.modalidade.toLowerCase()}</span>
                  </div>

                  <h2>{event.tema}</h2>
                  <p>
                    {event.descricao || 'Evento academico da Fatec Zona Leste.'}
                  </p>

                  <div className="public-event-card__meta">
                    <span>
                      <Clock aria-hidden="true" />
                      {event.horarioInicio} - {event.horarioFim}
                    </span>
                    <span>
                      <MapPin aria-hidden="true" />
                      {event.local || 'Local nao informado'}
                    </span>
                    {event.disciplina && (
                      <span>
                        <CalendarDays aria-hidden="true" />
                        {event.disciplina}
                      </span>
                    )}
                  </div>
                </div>

                <Link
                  className="public-event-card__action"
                  to={`/eventos/${event.id}`}
                >
                  Inscrever-se
                </Link>
              </article>
            )
          })}
        </section>
      )}
    </main>
  )
}

export default PublicEventList

import React, { useEffect, useState } from 'react'
import { Award, Copy, Search } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import db from '../../data/mockDb'
import type { MedalhaUsuarioResponse } from '../../data/types'
import {
  Button,
  Card,
  EmptyState,
  PageHeader,
  StatusBadge,
  UserMedalsSkeleton,
} from '../../components/ui'
import { toast } from '../../components/ui/Toast'

export const UserMedals: React.FC = () => {
  const navigate = useNavigate()
  const [search, setSearch] = useState('')
  const [medals, setMedals] = useState<MedalhaUsuarioResponse[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!db.getLoggedUser()) {
      navigate('/login')
    }
  }, [navigate])

  useEffect(() => {
    if (!db.getLoggedUser()) return

    setLoading(true)
    Promise.all([db.getMe(), db.getMyMedals()])
      .then(([, mdls]) => setMedals(mdls))
      .catch((err) => toast.error(err.message || 'Erro ao carregar medalhas.'))
      .finally(() => setLoading(false))
  }, [])

  if (!db.getLoggedUser()) return null
  if (loading) return <UserMedalsSkeleton />

  const filteredMedals = medals.filter(
    (medal) =>
      medal.nome.toLowerCase().includes(search.toLowerCase()) ||
      medal.tipo.toLowerCase().includes(search.toLowerCase()) ||
      (medal.evento?.tema || '').toLowerCase().includes(search.toLowerCase())
  )

  return (
    <div className="user-medals-container mobile-stack">
      <PageHeader
        eyebrow="Reconhecimento"
        title="Minhas medalhas"
        description="Conquistas academicas e tecnicas recebidas em eventos da FATEC Zona Leste."
        compact
      />

      <label className="mobile-search">
        <Search aria-hidden="true" />
        <input
          type="search"
          placeholder="Buscar por medalha ou evento"
          value={search}
          onChange={(event) => setSearch(event.target.value)}
        />
      </label>

      {filteredMedals.length === 0 ? (
        <EmptyState
          title={
            search
              ? 'Nenhuma medalha encontrada'
              : 'Voce ainda nao tem medalhas'
          }
          description={
            search
              ? 'Tente outro termo de busca.'
              : 'As medalhas recebidas aparecerao aqui com o evento relacionado.'
          }
        />
      ) : (
        <div className="achievement-grid">
          {filteredMedals.map((medal) => {
            const eventName = medal.evento?.tema || 'Evento'

            return (
              <Card
                key={medal.id}
                className={`achievement-card achievement-card--${medal.tipo.toLowerCase()}`}
              >
                <div className="achievement-card__header">
                  <div className="achievement-card__mark">
                    <Award aria-hidden="true" />
                  </div>
                  <span
                    className={`medal-type-badge medal-type-badge--${medal.tipo.toLowerCase()}`}
                  >
                    {medal.tipo}
                  </span>
                </div>
                <StatusBadge status="FINALIZADO" label={eventName} />
                <h2>{medal.nome}</h2>
                <p>
                  {medal.descricao ||
                    'Reconhecimento recebido por participacao academica.'}
                </p>
                <Button
                  variant="secondary"
                  size="sm"
                  icon={<Copy aria-hidden="true" />}
                  onClick={() => {
                    navigator.clipboard?.writeText(
                      `Recebi a medalha ${medal.tipo.toLowerCase()} "${medal.nome}" no evento ${eventName}.`
                    )
                  }}
                >
                  Copiar conquista
                </Button>
              </Card>
            )
          })}
        </div>
      )}
    </div>
  )
}

export default UserMedals
